cd /workspace && node -e "
const fs = require('fs');
const JSZip = require('jszip');

const NOTE = 'Note: All travel records for Maya Chen\\'s Seattle trip have been reviewed. Please verify the flight details and note that the hotel reservation was cancelled. Two car rentals are confirmed, and one was cancelled.';

(async () => {
  const data = fs.readFileSync('testbed/docs/travel_summary.docx');
  const zip = await JSZip.loadAsync(data);
  let xml = await zip.file('word/document.xml').async('string');

  // Build a new paragraph with the note
  const newPara = '<w:p><w:r><w:t>' + NOTE.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;') + '</w:t></w:r></w:p>';

  // Insert before closing </w:body>
  xml = xml.replace('</w:body>', newPara + '</w:body>');

  zip.file('word/document.xml', xml);
  const out = await zip.generateAsync({type: 'nodebuffer'});
  fs.writeFileSync('testbed/docs/travel_summary.docx', out);
  console.log('Document updated successfully.');
})();
"

