cd /workspace && node -e "
const mammoth = require('mammoth');
const PDFDocument = require('pdfkit');
const fs = require('fs');

(async () => {
  const result = await mammoth.extractRawText({path: 'testbed/docs/travel_summary.docx'});
  const lines = result.value.split('\n');

  const doc = new PDFDocument({margin: 50, size: 'A4'});
  const stream = fs.createWriteStream('testbed/docs/travel_summary.pdf');
  doc.pipe(stream);

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) {
      doc.moveDown(0.5);
      continue;
    }

    // Title
    if (trimmed === 'Travel Booking Summary') {
      doc.fontSize(18).font('Helvetica-Bold').text(trimmed, {align: 'center'});
      doc.moveDown(1);
    }
    // Section headers
    else if (['Flights', 'Hotels', 'Car Rentals'].includes(trimmed)) {
      doc.moveDown(0.5);
      doc.fontSize(14).font('Helvetica-Bold').text(trimmed);
      doc.moveDown(0.3);
      doc.moveTo(50, doc.y).lineTo(545, doc.y).stroke();
      doc.moveDown(0.5);
    }
    // Note line
    else if (trimmed.startsWith('Note:')) {
      doc.moveDown(1);
      doc.fontSize(10).font('Helvetica-Bold').text('Note: ', {continued: true});
      doc.font('Helvetica').text(trimmed.replace('Note: ', ''));
    }
    // Regular booking lines
    else {
      doc.fontSize(9).font('Helvetica').text(trimmed);
      doc.moveDown(0.2);
    }
  }

  doc.end();
  stream.on('finish', () => {
    const stats = fs.statSync('testbed/docs/travel_summary.pdf');
    console.log('PDF created successfully: testbed/docs/travel_summary.pdf (' + (stats.size / 1024).toFixed(1) + ' KB)');
  });
})();
"

